/* VetAI animal image map (extracted from index.html for caching/splitting; load order preserved) */
/* خريطة الصور (الاسم → المصدر) */
window.AIMG={
  pets:'data:image/webp;base64,',
  dog:'assets/animals/dog.webp',
  cat:'assets/animals/cat.webp',
  rabbit:'data:image/webp;base64,',
  cow:'assets/animals/cow.webp',
  sheep:'assets/animals/sheep.webp',
  horse:'assets/animals/horse.webp',
  parrots:'data:image/webp;base64,',
  fish:'data:image/webp;base64,',
  hen:'assets/animals/hen.webp',
  exotic:'data:image/webp;base64,',
  vet:'data:image/webp;base64,'
};
/* ربط بطاقات الأنواع (العربية) بمفاتيح الصور */
window.AI_SP={'كلاب':'dog','قطط':'cat','خيول':'horse','أبقار':'cow','أغنام':'sheep','دواجن':'hen','غريبة':'exotic','أسماك':'fish'};
/* يملأ كل <img data-ai="مفتاح"> بالصورة الصحيحة؛ التحميل الكسول يتولاه المتصفح عبر loading="lazy" */
window.aiFill=function(root){(root||document).querySelectorAll('img[data-ai]').forEach(function(i){var s=window.AIMG[i.dataset.ai];if(s&&i.getAttribute('src')!==s)i.src=s})};
document.addEventListener('DOMContentLoaded',function(){window.aiFill()});
